# login-modules.sh: L18 (B34) what one module costs to import in the real Shell. Re-imports each
# pure model module (no GObject classes, so a second copy is harmless) with a ?query, which
# re-reads, compiles and evaluates only that file (its imports come from the cache), and prints
# `FILE <ms> <bytes> <path>` by cost and `FILETOTAL`. Run on the idle Shell after login.
# (A class registered twice crashes the Shell, so GObject modules are not measured this way.)
# Alone: tools/harness/lib/bundle.sh /tmp/x.sh tools/harness/lib/lib.sh tools/scenarios/login-modules.sh
#        GUAVA_SKIP_PROBES=1 GUAVA_EXTRA=/tmp/x.sh tools/harness/run-f44.sh 0
echo "== login modules (import cost of pure modules)"
sleep 20
P "const e=Main.extensionManager.lookup('guava-os@blueyzx64'); const root=e.dir.get_path(); const files='lib/backgroundAppsModel.js lib/batteryModel.js lib/caretModel.js lib/clickModel.js lib/compatModel.js lib/iconStyleModel.js lib/inputRingModel.js lib/keybindingsModel.js lib/launcherEntryModel.js lib/lockModel.js lib/loginItemsModel.js lib/modalModel.js lib/mprisModel.js lib/pasteModel.js lib/wallpaperModel.js core/desktopActionsModel.js core/desktopLayersModel.js core/desktopModel.js core/layoutModel.js core/motionModel.js core/osdModel.js core/panelLayoutModel.js core/timersModel.js core/appMenus/model.js core/appMenus/nativeModel.js core/appMenus/setupModel.js core/widgets/model.js features/appButtons/greenButtonModel.js features/appButtons/model.js features/appearance/model.js features/calendar/model.js features/clipboard/model.js features/colorFilters/model.js features/controlCenter/customModel.js features/controlCenter/model.js features/desktopIcons/model.js features/dialogs/model.js features/emoji/model.js features/focus/model.js features/fullscreenSpace/model.js features/gestures/model.js features/hotCorners/model.js features/inputIndicator/model.js features/launchpad/model.js features/lowPower/model.js features/menuBar/model.js features/menuBarItems/model.js features/minimizeEffect/model.js features/missionControl/model.js features/notch/dashboardModel.js features/notch/downloadsModel.js features/notch/model.js features/notch/shelfHelperModel.js features/notificationCenter/model.js features/onboarding/model.js features/osd/model.js features/pointer/model.js features/roundedCorners/model.js features/screenshots/model.js features/shellBehaviour/model.js features/showDesktop/model.js features/splitView/model.js features/spotlight/actionsModel.js features/spotlight/model.js features/spotlight/queryModel.js features/stageManager/model.js features/switcher/model.js features/typography/model.js features/widgets/model.js features/windows/hideModel.js features/windows/model.js features/windows/snapModel.js features/windows/tileMotionModel.js features/stageManager/geometry.js features/emoji/data.js core/widgets/data.js'.split(' ').filter(Boolean); const out=[]; let k=0; for (const f of files){ const sz=e.dir.resolve_relative_path(f).load_contents(null)[1].length; const a=GLib.get_monotonic_time(); try{ await import('file://'+root+'/'+f+'?b='+(++k)); }catch(x){} out.push([Math.round((GLib.get_monotonic_time()-a)/100)/10,sz,f]); } globalThis.__kfiles=out; return out.length" >/dev/null
P "return globalThis.__kfiles.sort((a,b)=>b[0]-a[0]).map(r=>'FILE '+r[0]+' '+r[1]+' '+r[2]+' ;;').join(' ')+' FILETOTAL '+Math.round(globalThis.__kfiles.reduce((s,r)=>s+r[0],0))+' ;;'" | sed 's/;;/\n/g' | grep -o 'FILE[^\\]*'
